'use strict';

// MODULES //

var discreteUniform = require( '@stdlib/random/base/discrete-uniform' ).factory;
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isObject = require( '@stdlib/assert/is-plain-object' );
var isFunction = require( '@stdlib/assert/is-function' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns a pseudorandom number generator for performing random partition initialization.
*
* @private
* @param {PositiveInteger} k - number of clusters
* @param {boolean} hasOptions - boolean indicating whether to process an options argument
* @param {Options} [options] - function options
* @param {PRNG} [options.prng] - pseudorandom number generator which generates uniformly distributed pseudorandom numbers
* @param {PRNGSeedMT19937} [options.seed] - pseudorandom number generator seed
* @param {PRNGStateMT19937} [options.state] - pseudorandom number generator state
* @param {boolean} [options.copy=true] - boolean indicating whether to copy a provided pseudorandom number generator state
* @throws {TypeError} options argument must be an object
* @throws {TypeError} options.prng must be a pseudorandom number generator function
* @returns {Function} nullary pseudorandom number generator returning uniformly distributed pseudorandom integers on the closed interval `[0, k-1]`
*/
function prng( k, hasOptions, options ) {
	if ( hasOptions ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		if ( hasOwnProp( options, 'prng' ) && !isFunction( options.prng ) ) {
			throw new TypeError( format( 'invalid option. `%s` option must be a pseudorandom number generator function. Option: `%s`.', 'prng', options.prng ) );
		}
		return discreteUniform( 0, k-1, options );
	}
	return discreteUniform( 0, k-1 );
}


// EXPORTS //

module.exports = prng;
